document.addEventListener('DOMContentLoaded', function() {
    const slidesContainer = document.querySelector('.slides-container');
    const slides = document.querySelectorAll('.slide');
    const progressContainer = document.querySelector('.progress-container');
    const prevBtn = document.querySelector('.prev-btn');
    const nextBtn = document.querySelector('.next-btn');

    let currentSlide = 0;
    let players = [];
    let progressFills = [];

    // Create progress bars
    slides.forEach((_, index) => {
        const progressBar = document.createElement('div');
        progressBar.className = 'progress-bar';

        const progressFill = document.createElement('div');
        progressFill.className = 'progress-fill';
        progressFill.style.opacity = '0';

        progressBar.appendChild(progressFill);
        progressContainer.appendChild(progressBar);
        progressFills.push(progressFill);
    });

    // Initialize Vimeo Players
    function initializePlayers() {
        const iframes = document.querySelectorAll('.slide iframe');

        iframes.forEach((iframe, index) => {
            const player = new Vimeo.Player(iframe);
            players.push(player);

            player.on('loaded', () => {
                console.log(`Video ${index} loaded`);
                player.setVolume(0);
                player.setLoop(false);
                if (index === 0) startVideoAndProgress(index); // Start the first video directly
            });

            player.on('ended', () => {
                goToSlide(currentSlide + 1); // Go to the next slide when video ends
            });

            player.on('timeupdate', (data) => {
                if (index === currentSlide) { // Update progress only for the active slide
                	const progress = ((data.seconds * 1000) / (data.duration * 1000)) * 100;
                  progressFills[index].style.opacity = '1';
                  progressFills[index].style.width = `${progress}%`;
                }
            });
        });
    }

    // Start video and progress for a given slide
    function startVideoAndProgress(index) {
        progressFills.forEach((fill, i) => {
            if (i < index) {
                fill.style.width = '100%';
                fill.style.opacity = '1';
            } else if (i === index) {
                fill.style.width = '0%';
                fill.style.opacity = '1';
            } else {
                fill.style.width = '0%';
                fill.style.opacity = '0';
            }
        });

        players[index].setCurrentTime(0).then(() => {
            players[index].play().catch(error => {
                console.error(`Error playing video ${index}:`, error);
            });
        });
    }

    // Move to the next or previous slide
    function goToSlide(index) {
        if (index < 0) index = slides.length - 1;
        if (index >= slides.length) index = 0;

        players[currentSlide].pause();
        currentSlide = index;
        slidesContainer.style.transform = `translateX(-${currentSlide * 100}%)`;

        startVideoAndProgress(currentSlide);
    }

    // Button event listeners
    prevBtn.addEventListener('click', () => goToSlide(currentSlide - 1));
    nextBtn.addEventListener('click', () => goToSlide(currentSlide + 1));

    // Load the Vimeo Player API
    if (typeof Vimeo === 'undefined') {
        const script = document.createElement('script');
        script.src = 'https://player.vimeo.com/api/player.js';
        script.onload = initializePlayers;
        document.body.appendChild(script);
    } else {
        initializePlayers();
    }
});

