    }),
    playPauseButton = document.querySelector('.playPauseButton'),
    playIcon = document.querySelector('.playIcon'),
    pauseIcon = document.querySelector('.pauseIcon'),
    isPlaying = false;

function openModal() {
  overlay.classList.add('--Open')
  nav.style.zIndex = '97'
  showreelPlayer.play();
  isPlaying = true;
  updatePlayPauseIcon();
}

function closeModal() {
  overlay.classList.remove('--Open')
  showreelPlayer.pause()
  isPlaying = false;
  updatePlayPauseIcon();

  setTimeout(() => nav.style.zIndex = '99', 800)
}

function togglePlayPause() {
  if (isPlaying) {
    showreelPlayer.pause();
    isPlaying = false;
  } else {
    showreelPlayer.play();
    isPlaying = true;
  }
  updatePlayPauseIcon();
}

function updatePlayPauseIcon() {
  if (isPlaying) {
    playIcon.style.display = 'none';
    pauseIcon.style.display = 'block';
  } else {
    playIcon.style.display = 'block';
    pauseIcon.style.display = 'none';
  }
}

// Check showreelPlayer state
showreelPlayer.on('play', function() {
  isPlaying = true;
  updatePlayPauseIcon();
});

showreelPlayer.on('pause', function() {
  isPlaying = false;
  updatePlayPauseIcon();
});

