document.addEventListener('DOMContentLoaded', () => {
  document.querySelector('.copyright-year').innerHTML = new Date().getFullYear();

  const tooltip = document.querySelector('#tooltip');
  const closeButton = document.querySelector('.contact-form-overlay-close');
  const overlay = document.querySelector('.contact-form-overlay');
  const wrapper = document.querySelector('.contact-form-wrapper');

  // Function to determine if a point is inside the wrapper
  function isPointInWrapper(x, y) {
    const wrapperRect = wrapper.getBoundingClientRect();
    return (
      x >= wrapperRect.left &&
      x <= wrapperRect.right &&
      y >= wrapperRect.top &&
      y <= wrapperRect.bottom
    );
  }

  function moveTooltip(e) {
    tooltip.style.left = `${e.clientX}px`;
    tooltip.style.top = `${e.clientY}px`;
  }

  function moveCloseButton(e) {
    closeButton.style.left = `${e.clientX - 28}px`;
    closeButton.style.top = `${e.clientY - 28}px`;
  }

  tooltip.style.display = 'none';
  closeButton.style.display = 'none';

  function showTooltip(text) {
    tooltip.style.display = 'block';
    tooltip.style.position = 'fixed';
    tooltip.style.zIndex = '999';

    tooltip.innerHTML = text;
  }

  function showCloseButton() {
    closeButton.style.display = 'flex';
    closeButton.style.position = 'fixed';
    closeButton.style.zIndex = '999';
  }

  function hideTooltip() {
    tooltip.style.display = 'none';
  }

  function hideCloseButton() {
    closeButton.style.display = 'none';
  }

  const tooltipElements = document.querySelectorAll('[data-tooltip]');

  tooltipElements.forEach(element => {
    element.addEventListener('mousemove', moveTooltip);
    element.addEventListener('mouseenter', (e) => {
      showTooltip(element.dataset.tooltip);
      moveTooltip(e);
    });
    element.addEventListener('mouseleave', hideTooltip);
  });

  // The main mouse move handler for the overlay
  overlay.addEventListener('mousemove', (e) => {
    // Check if the current mouse position is inside the wrapper
    if (isPointInWrapper(e.clientX, e.clientY)) {
      hideCloseButton();
    } else {
      showCloseButton();
      moveCloseButton(e);
    }
  });


  // Initial visibility when entering the overlay
  overlay.addEventListener('mouseenter', (e) => {
    if (!isPointInWrapper(e.clientX, e.clientY)) {
      showCloseButton();
      moveCloseButton(e);
    }
  });

  // Hide when leaving the overlay completely
  overlay.addEventListener('mouseleave', hideCloseButton);
})

  document.addEventListener('DOMContentLoaded', () => {
const stats = document.querySelector("#stats");

function startCounting(counters) {
  counters.forEach((counter) => {
    // Get the data-count value
    const finalValue = counter.getAttribute("data-count");

    // Check if the value has a plus sign at the beginning
    const hasPlus = finalValue.startsWith("+");

    // Extract the numeric part (including the + if it exists)
    const numericMatch = finalValue.match(/[-+]?\d+(\.\d+)?/);

    if (!numericMatch) return; // Skip if no numeric value found

    // Get the pure numeric value (without the + sign)
    const numericValue = parseFloat(numericMatch[0]);

    // Find where the number starts in the original string
    const numericString = numericMatch[0];
    const numericIndex = finalValue.indexOf(numericString);

    // Get the prefix (everything before the number, excluding the + if it's part of the number)
    const prefix = hasPlus 
      ? finalValue.substring(0, numericIndex + 1) // Include the + in the prefix
      : finalValue.substring(0, numericIndex);

    // Get the suffix (everything after the number)
    const suffix = finalValue.substring(numericIndex + numericString.length);

    // Custom object to animate
    const obj = { value: 0 };

    // Set up the animation
    anime({
      targets: obj,
      value: numericValue, // Target the final numeric value (without the + sign)
      easing: "easeInOutSine",
      duration: 2000,
      round: 10, // Use round: 10 as requested
      update: function() {
        // Get the current value
        let currentValue = obj.value;

        // Update the counter with prefix, current value, and suffix
        counter.innerHTML = prefix + currentValue + suffix;
      }
    });
  });
}

if (stats) {
  const counters = stats.querySelectorAll("[data-count]");

  const options = {
    root: null,
    rootMargin: "0px",
    threshold: 0.5,
  };

  const observer = new IntersectionObserver((entries) => {
    entries.forEach((entry) => {
      if (entry.isIntersecting) {
        startCounting(counters);
        //observer.unobserve(entry.target); // Only trigger once
      }
    });
  }, options);

  observer.observe(stats);
}
  })

